@implements IAsyncDisposable
@inject IJSRuntime JS

<div class="message-area">
    <div class="message-area-header">
        <h2># @Channel.Name</h2>
        <p>@Channel.Description</p>
    </div>

    <div class="message-list" id="@_messageListId">
        @if (HasMoreMessages)
        {
            <div id="@_sentinelId" class="load-sentinel">
                @if (IsLoadingMore)
                {
                    <span class="loading-text">Loading older messages...</span>
                }
            </div>
        }

        @foreach (var message in Messages.Where(m => m.ReplyToId is null))
        {
            <MessageBubble Message="message"
                           ThreadInfo="GetThreadInfo(message.Id)"
                           OnOpenThread="OnOpenThread"
                           OnReact="OnReact" />
        }
    </div>

    <MessageInput Placeholder="@($"Message #{Channel.Name}")"
                  ButtonText="Send"
                  OnSubmit="OnSendMessage" />
</div>

@code {
    [Parameter, EditorRequired] public Channel Channel { get; set; } = default!;
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public bool HasMoreMessages { get; set; }
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private readonly string _messageListId = $"msg-list-{Guid.NewGuid():N}";
    private readonly string _sentinelId = $"sentinel-{Guid.NewGuid():N}";
    private IJSObjectReference? _jsModule;
    private DotNetObjectReference<MessageArea>? _dotnetRef;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _jsModule = await JS.InvokeAsync<IJSObjectReference>("import", "./js/chat-scroll.js");
            _dotnetRef = DotNetObjectReference.Create(this);
            await _jsModule.InvokeVoidAsync("observeSentinel", _sentinelId, _dotnetRef);
            await _jsModule.InvokeVoidAsync("scrollToBottom", _messageListId);
        }
    }

    [JSInvokable]
    public async Task OnSentinelVisible()
    {
        if (!IsLoadingMore)
        {
            await OnLoadMore.InvokeAsync();
        }
    }

    public async Task ScrollToBottom()
    {
        if (_jsModule is not null)
        {
            await _jsModule.InvokeVoidAsync("scrollToBottom", _messageListId);
        }
    }

    private ThreadSummary? GetThreadInfo(int messageId) =>
        ThreadSummaries.FirstOrDefault(t => t.RootMessageId == messageId);

    public async ValueTask DisposeAsync()
    {
        if (_jsModule is not null)
        {
            try
            {
                await _jsModule.InvokeVoidAsync("disposeSentinel", _sentinelId);
                await _jsModule.DisposeAsync();
            }
            catch (JSDisconnectedException)
            {
                // Circuit disconnected, nothing to clean up
            }
        }
        _dotnetRef?.Dispose();
    }
}

