arguments.file_text:
@page "/chat"
@rendermode InteractiveServer
@using sv_adf3189786cd42fa8180a496846d5901.Services
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelSidebar Channels="_channels"
                        SelectedChannelId="_selectedChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(_selectedThreadRootId.HasValue ? "thread-open" : "")">
        @if (_selectedChannel is not null)
        {
            <MessageArea @ref="_messageAreaRef"
                         Channel="_selectedChannel"
                         Messages="_messages"
                         ThreadSummaries="_threadSummaries"
                         HasMoreMessages="_hasMoreMessages"
                         IsLoadingMore="_isLoadingMore"
                         OnOpenThread="OpenThread"
                         OnReact="HandleReaction"
                         OnSendMessage="SendMessage"
                         OnLoadMore="LoadMoreMessages" />
        }
        else
        {
            <div class="no-channel">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (_selectedThreadRootId.HasValue && _threadRootMessage is not null)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="_threadRootMessage"
                         Replies="_threadMessages"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel> _channels = [];
    private int? _selectedChannelId;
    private Channel? _selectedChannel;
    private List<Message> _messages = [];
    private List<ThreadSummary> _threadSummaries = [];
    private bool _hasMoreMessages = true;
    private bool _isLoadingMore;
    private const int PageSize = 50;

    private int? _selectedThreadRootId;
    private Message? _threadRootMessage;
    private List<Message> _threadMessages = [];

    private MessageArea? _messageAreaRef;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
    }

    private async Task SelectChannel(int channelId)
    {
        if (_selectedChannelId == channelId) return;

        _selectedChannelId = channelId;
        _selectedChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _messages = [];
        _threadSummaries = [];
        _hasMoreMessages = true;
        _selectedThreadRootId = null;
        _threadRootMessage = null;
        _threadMessages = [];

        var loaded = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _messages = loaded;
        _hasMoreMessages = loaded.Count == PageSize;

        BuildThreadSummaries();

        await ChatService.MarkChannelReadAsync(channelId);

        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            _channels[idx] = _channels[idx] with { UnreadCount = 0 };
        }
    }

    private async Task LoadMoreMessages()
    {
        if (_isLoadingMore || !_hasMoreMessages || _selectedChannelId is null) return;

        _isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_selectedChannelId.Value, _messages.Count, PageSize);
        _hasMoreMessages = older.Count == PageSize;
        _messages.InsertRange(0, older);
        BuildThreadSummaries();

        _isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (_selectedChannelId is null) return;

        var message = await ChatService.SendMessageAsync(_selectedChannelId.Value, content, null);
        _messages.Add(message);

        if (_messageAreaRef is not null)
        {
            await _messageAreaRef.ScrollToBottom();
        }
    }

    private async Task OpenThread(int rootMessageId)
    {
        _selectedThreadRootId = rootMessageId;
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        _threadMessages = await ChatService.GetThreadAsync(rootMessageId);
    }

    private void CloseThread()
    {
        _selectedThreadRootId = null;
        _threadRootMessage = null;
        _threadMessages = [];
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        var msg = _messages.FirstOrDefault(m => m.Id == args.MessageId);
        if (msg is not null)
        {
            var reaction = msg.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
            if (reaction is not null)
            {
                reaction.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(args.Emoji, ["You"]));
            }
        }
    }

    private async Task SendThreadReply(string content)
    {
        if (_selectedThreadRootId is null || _selectedChannelId is null) return;

        var reply = await ChatService.SendMessageAsync(_selectedChannelId.Value, content, _selectedThreadRootId);
        _threadMessages.Add(reply);

        var existing = _threadSummaries.FirstOrDefault(t => t.RootMessageId == _selectedThreadRootId);
        if (existing is not null)
        {
            _threadSummaries.Remove(existing);
        }
        _threadSummaries.Add(new ThreadSummary(_selectedThreadRootId.Value, _threadMessages.Count, DateTime.UtcNow));
    }

    private void BuildThreadSummaries()
    {
        var replyGroups = _messages
            .Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value);

        _threadSummaries = replyGroups
            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
            .ToList();
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.chat-main {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
}

.chat-main.thread-open {
    /* Main area shrinks when thread is visible */
}

.chat-thread {
    width: 25%;
    min-width: 280px;
    max-width: 400px;
    flex-shrink: 0;
}

.no-channel {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #888;
    font-size: 1.1rem;
}

